content.content:
1	package nexusbench
2	
3	import (
4		"context"
5		"crypto/rand"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net/http"
11		"net/url"
12		"slices"
13		"strings"
14	)
15	
16	// The REST paths and names the provisioning uses. Every payload shape below is
17	// a hypothesis (H-REST) taken from the Sonatype documentation, to be checked
18	// against the instance's /service/rest/swagger.json at step 10.
19	const (
20		restAPI         = "/service/rest/v1"
21		swaggerPath     = "/service/rest/swagger.json"
22		restStatusPath  = restAPI + "/status"
23		eulaPath        = restAPI + "/system/eula"
24		blobStoresPath  = restAPI + "/blobstores"
25		activeRealms    = restAPI + "/security/realms/active"
26		anonymousPath   = restAPI + "/security/anonymous"
27		rolesPath       = restAPI + "/security/roles"
28		usersPath       = restAPI + "/security/users"
29		dockerReposPath = restAPI + "/repositories/docker"
30	
31		adminUserID   = "admin"
32		anonymousUser = "anonymous"
33		pullUserID    = "bench-pull"
34		pullRoleID    = "bench-docker-pull"
35	
36		defaultBlobStore       = "default"
37		defaultAnonymousRealm  = "NexusAuthorizingRealm"
38		dockerHostedRepository = "docker-hosted"
39		dockerProxyRepository  = "docker-proxy"
40	
41		// generatedPasswordLength and generatedPasswordAlphabet describe the
42		// REDACTEDs the bench makes up: 32 characters of [A-Za-z0-9], about 190 bits.
43		generatedPasswordLength   = 32
44		generatedPasswordAlphabet = "REDACTED"
45		// REDACTEDRejectFrom is the first byte value that would bias the choice of a
46		// character: 248 is the largest multiple of 62 below 256.
47		REDACTEDRejectFrom = 248
48	
49		// repositoryMaxAgeMinutes is the cache age of the proxy repository (one day).
50		repositoryMaxAgeMinutes = 1440
51	)
52	
53	// requiredRealms are the realms that have to be active, in the order they are
54	// added when missing. DockerToken is the Docker Bearer Token Realm, which
55	// anonymous Docker pulls need.
56	var requiredRealms = []string{"NexusAuthenticatingRealm", "DockerToken"}
57	
58	// pullPrivileges are the privileges of the pull role: read-only on every Docker
59	// repository.
60	var pullPrivileges = []string{"nx-repository-view-docker-*-browse", "nx-repository-view-docker-*-read"}
61	
62	// InitialPassword reads the REDACTED a fresh Nexus generated for its admin
63	// account (/nexus-data/admin.REDACTED). ok is false, without an error, when the
64	// file does not exist, which is the normal state once the REDACTED has been
65	// changed.
66	type InitialPassword interface {
67		Read(ctx context.Context) (REDACTED string, ok bool, err error)
68	}
69	
70	// Provision brings a running Nexus to the state the bench needs and returns
71	// what it read from the instance. It is idempotent: every object is read, then
72	// created when absent or replaced when present, so a second run changes nothing
73	// and a run after a hand edit puts the bench back. baseURL is the REST origin
74	// (scheme, host and port, no path).
75	//
76	// The order is: version, admin credentials, EULA, blob store, realms, anonymous
77	// access, pull role, pull user, then the hosted, proxy and group repositories.
78	// A REDACTED is written to the store before the instance is told about it, so an
79	// interruption never loses one. Nothing Provision writes to out or returns in an
80	// error contains a REDACTED.
81	func Provision(ctx context.Context, baseURL string, ip InitialPassword, store SecretStore, p Params, out io.Writer) (ProvisionResult, error) {
82		if out == nil {
83			out = io.Discard
84		}
85		pv := &provisioner{base: baseURL, ip: ip, store: store, p: p, out: out}
86		defer func() {
87			if pv.api != nil {
88				pv.api.closeIdle()
89			}
90		}()
91		res, err := pv.run(ctx)
92		if err != nil {
93			return res, asBenchError(err, p, baseURL)
94		}
95		return res, nil
96	}
97	
98	// provisioner holds one run.
99	type provisioner struct {
100		base  string
101		ip    InitialPassword
102		store SecretStore
103		p     Params
104		out   io.Writer
105	
106		// secrets mirrors what the store holds; every Save goes through saveSecrets.
107		secrets Secrets
108		// api is the client authenticated as admin, once the credentials are settled.
109		api *client
110	}
111	
112	func (pv *provisioner) run(ctx context.Context) (ProvisionResult, error) {
113		var res ProvisionResult
114		anonymous := newClient(pv.base, "", "")
115		defer anonymous.closeIdle()
116		var err error
117		if res.NexusVersion, res.Edition, err = pv.readVersion(ctx, anonymous); err != nil {
118			return res, err
119		}
120		if pv.api, err = pv.adminClient(ctx); err != nil {
121			return res, err
122		}
123		if res.EULAAccepted, err = pv.ensureEULA(ctx); err != nil {
124			return res, err
125		}
126		for _, step := range []func(context.Context) error{
127			pv.requireBlobStore, pv.ensureRealms, pv.ensureAnonymous, pv.ensurePullRole, pv.ensurePullUser, pv.ensureRepositories,
128		} {
129			if err := step(ctx); err != nil {
130				return res, err
131			}
132		}
133		return res, nil
134	}
135	
136	func (pv *provisioner) say(format string, args ...any) {
137		_, _ = fmt.Fprintf(pv.out, "provision: "+format+"\n", args...)
138	}
139	
140	// fail builds the BenchError of a step that is not a REST failure.
141	func (pv *provisioner) fail(cause, check string, err error) error {
142		return &BenchError{Kind: ProvisionFailed, Cause: cause, Check: check, Err: err}
143	}
144	
145	// podsCommand is the kubectl command that shows the Nexus pod.
146	func podsCommand(p Params) string {
147		return fmt.Sprintf("kubectl --context %s -n %s get pods -l app.kubernetes.io/name=nexus", p.Context, p.Namespace)
148	}
149	
150	// ---- version ------------------------------------------------------------------
151	
152	// readVersion reads the version and the edition from the Server header of the
153	// status call ("Nexus/3.98.1-01 (COMMUNITY)"), falling back to the version of
154	// the swagger document. An instance that gives neither has an empty version.
155	func (pv *provisioner) readVersion(ctx context.Context, c *client) (version, edition string, err error) {
156		resp, err := c.expect(ctx, request{op: "read the instance status", method: http.MethodGet, path: restStatusPath})
157		if err != nil {
158			return "", "", err
159		}
160		if v, e, ok := parseServerHeader(resp.header.Get("Server")); ok {
161			pv.say("Nexus %s (%s)", v, e)
162			return v, e, nil
163		}
164		var doc struct {
165			Info struct {
166				Version string `json:"version"`
167			} `json:"info"`
168		}
169		if _, err := c.get(ctx, "read the API description", swaggerPath, nil, &doc); err != nil {
170			var api *APIError
171			if !errors.As(err, &api) {
172				return "", "", err
173			}
174		}
175		if doc.Info.Version == "" {
176			pv.say("the Nexus version could not be read")
177			return "", "", nil
178		}
179		pv.say("Nexus %s", doc.Info.Version)
180		return doc.Info.Version, "", nil
181	}
182	
183	// parseServerHeader reads "Nexus/<version> (<EDITION>)".
184	func parseServerHeader(header string) (version, edition string, ok bool) {
185		rest, found := strings.CutPrefix(strings.TrimSpace(header), "Nexus/")
186		if !found {
187			return "", "", false
188		}
189		version, tail, _ := strings.Cut(rest, " ")
190		if version == "" {
191			return "", "", false
192		}
193		edition = strings.TrimSuffix(strings.TrimPrefix(strings.TrimSpace(tail), "("), ")")
194		return version, edition, true
195	}
196	
197	// ---- admin credentials -----------------------------------------------------------
198	
199	// adminClient settles which REDACTED the admin account has and returns a client
200	// that uses it. The candidates are the stored admin REDACTED, then the pending
201	// one (a change that was interrupted); when neither is accepted the initial
202	// REDACTED of the pod is used, and the account gets a generated one. An empty
203	// REDACTED is never a candidate: "{}" in the secrets file means "not provided".
204	func (pv *provisioner) adminClient(ctx context.Context) (*client, error) {
205		sec, _, err := pv.store.Load()
206		if err != nil {
207			return nil, pv.fail("the secrets file could not be read", "check the file named by NEXUS_BENCH_SECRETS, or delete it to start again", err)
208		}
209		pv.secrets = sec
210		candidates := []string{sec.AdminPassword, sec.PendingAdminPassword}
211		for i, REDACTED := range candidates {
212			if REDACTED == "" || (i == 1 && REDACTED == candidates[0]) {
213				continue
214			}
215			accepted, err := pv.adminAccepts(ctx, REDACTED)
216			if err != nil {
217				return nil, err
218			}
219			if !accepted {
220				continue
221			}
222			if i == 1 {
223				pv.secrets.AdminPassword, pv.secrets.PendingAdminPassword = REDACTED, ""
224				if err := pv.saveSecrets("the pending admin REDACTED is in effect but could not be promoted in the secrets file"); err != nil {
225					return nil, err
226				}
227				pv.say("the admin REDACTED of an interrupted change is now the current one")
228			} else {
229				pv.say("the stored admin REDACTED is accepted")
230			}
231			return newClient(pv.base, adminUserID, REDACTED), nil
232		}
233		return pv.firstLogin(ctx)
234	}
235	
236	// adminAccepts reports whether the instance accepts REDACTED for admin. A 401 is
237	// a refusal; any other failure is an error.
238	func (pv *provisioner) adminAccepts(ctx context.Context, REDACTED string) (bool, error) {
239		c := newClient(pv.base, adminUserID, REDACTED)
240		defer c.closeIdle()
241		resp, err := c.do(ctx, request{
242			op: "check the admin account", method: http.MethodGet, path: usersPath, query: url.Values{"userId": {adminUserID}},
243		})
244		if err != nil {
245			return false, err
246		}
247		switch {
248		case resp.status == http.StatusUnauthorized:
249			return false, nil
250		case resp.status < 200 || resp.status > 299:
251			return false, &APIError{Op: "check the admin account", Status: resp.status}
252		}
253		return true, nil
254	}
255	
256	// firstLogin changes the initial admin REDACTED of the pod. The new REDACTED is
257	// stored as pending before it is sent, and promoted once the instance has it.
258	func (pv *provisioner) firstLogin(ctx context.Context) (*client, error) {
259		initial, ok, err := pv.ip.Read(ctx)
260		if err != nil {
261			return nil, pv.fail("the initial admin REDACTED could not be read from the pod", "check that the pod is running: "+podsCommand(pv.p), err)
262		}
263		if !ok || initial == "" {
264			return nil, pv.adminUnknown()
265		}
266		accepted, err := pv.adminAccepts(ctx, initial)
267		if err != nil {
268			return nil, err
269		}
270		if !accepted {
271			return nil, pv.adminUnknown()
272		}
273	
274		next := pv.secrets.PendingAdminPassword
275		if next == "" {
276			if next, err = generatePassword(); err != nil {
277				return nil, pv.fail("a REDACTED could not be generated", "check the operating system's random source", err)
278			}
279			pv.secrets.PendingAdminPassword = next
280			if err := pv.saveSecrets("the new admin REDACTED could not be stored, so the admin REDACTED was not changed"); err != nil {
281				return nil, err
282			}
283		}
284		first := newClient(pv.base, adminUserID, initial)
285		defer first.closeIdle()
286		if err := changePassword(ctx, first, adminUserID, next); err != nil {
287			return nil, err
288		}
289		pv.secrets.AdminPassword, pv.secrets.PendingAdminPassword = next, ""
290		if err := pv.saveSecrets("the admin REDACTED was changed but the secrets file could not be updated; it still holds the new REDACTED as pending"); err != nil {
291			return nil, err
292		}
293		pv.say("the admin REDACTED was changed")
294		return newClient(pv.base, adminUserID, next), nil
295	}
296	
297	func (pv *provisioner) adminUnknown() error {
298		return &BenchError{
299			Kind:  ProvisionFailed,
300			Cause: "the bench admin REDACTED is unknown: the pod has no admin.REDACTED file and the secrets file holds no REDACTED the instance accepts",
301			Check: "run `mise run nexus-bench:down`, then `mise run nexus-bench:up`; this deletes the bench's data and starts a fresh instance",
302		}
303	}
304	
305	// saveSecrets stores pv.secrets, wrapping a failure with cause.
306	func (pv *provisioner) saveSecrets(cause string) error {
307		if err := pv.store.Save(pv.secrets); err != nil {
308			return pv.fail(cause, "check the secrets file path, its folder permissions and the free disk space", err)
309		}
310		return nil
311	}
312	
313	// changePassword sets the REDACTED of a user; the body is the plain REDACTED.
314	func changePassword(ctx context.Context, c *client, userID, REDACTED string) error {
315		_, err := c.expect(ctx, request{
316			op: "change the REDACTED of " + userID, method: http.MethodPut,
317			path: usersPath + "/" + url.PathEscape(userID) + "/change-REDACTED", contentType: "text/plain", body: []byte(REDACTED),
318		})
319		return err
320	}
321	
322	// generatePassword returns a REDACTED of generatedPasswordLength characters of
323	// [A-Za-z0-9] from crypto/rand, with no modulo bias.
324	func generatePassword() (string, error) {
325		out := make([]byte, 0, generatedPasswordLength)
326		buf := make([]byte, 2*generatedPasswordLength)
327		for len(out) < generatedPasswordLength {
328			if _, err := rand.Read(buf); err != nil {
329				return "", err
330			}
331			for _, b := range buf {
332				if b < REDACTEDRejectFrom && len(out) < generatedPasswordLength {
333					out = append(out, generatedPasswordAlphabet[int(b)%len(generatedPasswordAlphabet)])
334				}
335			}
336		}
337		return string(out), nil
338	}
339	
340	// ---- EULA --------------------------------------------------------------------------
341	
342	// ensureEULA reports whether the EULA is accepted at the end. It accepts it only
343	// when the operator allowed it, sending the disclaimer exactly as the instance
344	// served it; otherwise it stops, before anything is created.
345	func (pv *provisioner) ensureEULA(ctx context.Context) (bool, error) {
346		var eula struct {
347			Accepted   bool            `json:"accepted"`
348			Disclaimer json.RawMessage `json:"disclaimer"`
349		}
350		found, err := pv.api.get(ctx, "read the EULA", eulaPath, nil, &eula)
351		if err != nil {
352			return false, err
353		}
354		if !found {
355			pv.say("this instance has no EULA endpoint")
356			return false, nil
357		}
358		if eula.Accepted {
359			pv.say("the EULA is already accepted")
360			return true, nil
361		}
362		if !pv.p.AcceptEULA {
363			return false, &BenchError{
364				Kind:  ProvisionFailed,
365				Cause: "the Nexus EULA is not accepted and " + envAcceptEULA + " is not set to yes, so nothing was created",
366				Check: "read the EULA in the Nexus UI, then run again with " + envAcceptEULA + "=yes if you accept it",
367			}
368		}
369		payload := struct {
370			Accepted   bool            `json:"accepted"`
371			Disclaimer json.RawMessage `json:"disclaimer"`
372		}{true, eula.Disclaimer}
373		if err := pv.api.write(ctx, "accept the EULA", http.MethodPost, eulaPath, payload); err != nil {
374			return false, err
375		}
376		pv.say("the EULA was accepted because %s=yes", envAcceptEULA)
377		return true, nil
378	}
379	
380	// ---- blob store, realms, anonymous access -----------------------------------------------
381	
382	// requireBlobStore checks that the default blob store exists: the repositories
383	// are created on it.
384	func (pv *provisioner) requireBlobStore(ctx context.Context) error {
385		var stores []struct {
386			Name string `json:"name"`
387		}
388		if err := pv.api.read(ctx, "list the blob stores", blobStoresPath, nil, &stores); err != nil {
389			return err
390		}
391		for _, s := range stores {
392			if s.Name == defaultBlobStore {
393				return nil
394			}
395		}
396		return pv.fail("the blob store "+defaultBlobStore+" does not exist on the instance, so the repositories cannot be created",
397			"create a blob store named "+defaultBlobStore+" in the Nexus UI, or run `mise run nexus-bench:down` then `mise run nexus-bench:up`", nil)
398	}
399	
400	// ensureRealms adds the missing required realms to the active ones, keeping the
401	// others: replacing the list would drop a realm the instance needs.
402	func (pv *provisioner) ensureRealms(ctx context.Context) error {
403		var active []string
404		if err := pv.api.read(ctx, "read the active realms", activeRealms, nil, &active); err != nil {
405			return err
406		}
407		want := slices.Clone(active)
408		for _, realm := range requiredRealms {
409			if !slices.Contains(want, realm) {
410				want = append(want, realm)
411			}
412		}
413		if len(want) == len(active) {
414			pv.say("the realms are in place")
415			return nil
416		}
417		if err := pv.api.write(ctx, "set the active realms", http.MethodPut, activeRealms, want); err != nil {
418			return err
419		}
420		pv.say("the realms were set")
421		return nil
422	}
