424	// ensureAnonymous sets whether anonymous access is enabled, keeping the realm of
425	// the anonymous user as the instance has it.
426	func (pv *provisioner) ensureAnonymous(ctx context.Context) error {
427		var current struct {
428			RealmName string `json:"realmName"`
429		}
430		if err := pv.api.read(ctx, "read the anonymous access", anonymousPath, nil, &current); err != nil {
431			return err
432		}
433		if current.RealmName == "" {
434			current.RealmName = defaultAnonymousRealm
435		}
436		payload := map[string]any{"enabled": pv.p.Anonymous, "userId": anonymousUser, "realmName": current.RealmName}
437		if err := pv.api.write(ctx, "set the anonymous access", http.MethodPut, anonymousPath, payload); err != nil {
438			return err
439		}
440		pv.say("anonymous access enabled: %t", pv.p.Anonymous)
441		return nil
442	}
