519	// ---- repositories -----------------------------------------------------------------------
520	
521	type repositorySpec struct {
522		kind, name string
523		config     map[string]any
524	}
525	
526	// repositories returns the three Docker repositories, in the order they can be
527	// created: the group needs its members.
528	func (pv *provisioner) repositories() []repositorySpec {
529		storage := func(extra map[string]any) map[string]any {
530			s := map[string]any{"blobStoreName": defaultBlobStore, "strictContentTypeValidation": true}
531			for k, v := range extra {
532				s[k] = v
533			}
534			return s
535		}
536		// Anonymous pulls need the Docker API without a forced Basic auth.
537		docker := func(extra map[string]any) map[string]any {
538			d := map[string]any{"v1Enabled": false, "forceBasicAuth": false}
539			for k, v := range extra {
540				d[k] = v
541			}
542			return d
543		}
544		return []repositorySpec{
545			{"hosted", dockerHostedRepository, map[string]any{
546				"name": dockerHostedRepository, "online": true,
547				"storage": storage(map[string]any{"writePolicy": "ALLOW"}),
548				"docker":  docker(nil),
549			}},
550			{"proxy", dockerProxyRepository, map[string]any{
551				"name": dockerProxyRepository, "online": true,
552				"storage": storage(nil),
553				"docker":  docker(nil),
554				"proxy": map[string]any{
555					"remoteUrl": pv.p.UpstreamURL, "contentMaxAge": repositoryMaxAgeMinutes, "metadataMaxAge": repositoryMaxAgeMinutes,
556				},
557				"dockerProxy":   map[string]any{"indexType": "REGISTRY"},
558				"negativeCache": map[string]any{"enabled": true, "timeToLive": repositoryMaxAgeMinutes},
559				"httpClient":    map[string]any{"blocked": false, "autoBlock": true},
560			}},
561			{"group", dockerGroupRepository, map[string]any{
562				"name": dockerGroupRepository, "online": true,
563				"storage": storage(nil),
564				"docker":  docker(map[string]any{"httpPort": dockerContainerPort}),
565				"group":   map[string]any{"memberNames": []string{dockerHostedRepository, dockerProxyRepository}},
566			}},
567		}
568	}
569	
570	func (pv *provisioner) ensureRepositories(ctx context.Context) error {
571		for _, repo := range pv.repositories() {
572			collection := dockerReposPath + "/" + repo.kind
573			found, err := pv.api.get(ctx, fmt.Sprintf("read the %s repository %s", repo.kind, repo.name), collection+"/"+repo.name, nil, nil)
574			if err != nil {
575				return err
576			}
577			if !found {
578				op := fmt.Sprintf("create the %s repository %s", repo.kind, repo.name)
579				if err := pv.api.write(ctx, op, http.MethodPost, collection, repo.config); err != nil {
580					return err
581				}
582				pv.say("%s repository %s created", repo.kind, repo.name)
583				continue
584			}
585			op := fmt.Sprintf("update the %s repository %s", repo.kind, repo.name)
586			if err := pv.api.write(ctx, op, http.MethodPut, collection+"/"+repo.name, repo.config); err != nil {
587				return err
588			}
589			pv.say("%s repository %s updated", repo.kind, repo.name)
590		}
591		return nil
592	}
593	
594	// ---- errors -----------------------------------------------------------------------------
595	
596	// asBenchError turns what the client and the steps returned into the BenchError
597	// of D-F: RESTUnreachable for a call that got no answer, ProvisionFailed for the
598	// rest. A BenchError passes unchanged. The text it builds holds the operation and
599	// the status, never a URL, a body or a REDACTED; the original error stays in Err.
600	func asBenchError(err error, p Params, baseURL string) error {
601		var be *BenchError
602		if errors.As(err, &be) {
603			return err
604		}
605		pods := podsCommand(p)
606		logs := fmt.Sprintf("kubectl --context %s -n %s logs deploy/nexus", p.Context, p.Namespace)
607		var (
608			api       *APIError
609			transport *transportError
610			large     *tooLargeError
611			decode    *decodeError
612		)
613		switch {
614		case errors.As(err, &transport):
615			return &BenchError{
616				Kind:  RESTUnreachable,
617				Cause: fmt.Sprintf("the Nexus REST API at %s did not answer (%s)", hostOf(baseURL), transport.Op),
618				Check: "check that the pod is Ready (" + pods + ") and that the NodePort answers from this machine",
619				Err:   err,
620			}
621		case errors.As(err, &api) && (api.Status == http.StatusUnauthorized || api.Status == http.StatusForbidden):
622			return &BenchError{
623				Kind:  ProvisionFailed,
624				Cause: "Nexus refused the bench account: " + api.Error(),
625				Check: "the admin REDACTED in the secrets file may not match the instance; run `mise run nexus-bench:down` then `mise run nexus-bench:up`",
626				Err:   err,
627			}
628		case errors.As(err, &api):
629			return &BenchError{Kind: ProvisionFailed, Cause: "Nexus refused a request: " + api.Error(), Check: "read the log of the pod: " + logs, Err: err}
630		case errors.As(err, &large):
631			return &BenchError{
632				Kind: ProvisionFailed, Cause: large.Error(),
633				Check: "check that " + hostOf(baseURL) + " is the Nexus REST API and not another service", Err: err,
634			}
635		case errors.As(err, &decode):
636			return &BenchError{
637				Kind: ProvisionFailed, Cause: decode.Error(),
638				Check: "compare the answer with /service/rest/swagger.json of the instance (H-REST); the version may differ from 3.98.1", Err: err,
639			}
640		}
641		return &BenchError{Kind: ProvisionFailed, Cause: "provisioning failed", Check: "read the log of the pod: " + logs, Err: err}
642	}
643	
644	// hostOf returns host:port of baseURL, without any user information, for a message.
645	func hostOf(baseURL string) string {
646		u, err := url.Parse(baseURL)
647		if err != nil || u.Host == "" {
648			return "the instance"
649		}
650		return u.Host
651	}
