145	// podsCommand is the kubectl command that shows the Nexus pod.
146	func podsCommand(p Params) string {
147		return fmt.Sprintf("kubectl --context %s -n %s get pods -l app.kubernetes.io/name=nexus", p.Context, p.Namespace)
148	}
