469	// userRef is the part of a user the provisioning reads back.
470	type userRef struct {
471		UserID string `json:"userId"`
472	}
473	
474	// ensurePullUser creates or replaces the read-only user. Its REDACTED is stored
475	// before the instance gets it. The list call filters by substring, so the
476	// element of the exact id is the one that counts.
477	func (pv *provisioner) ensurePullUser(ctx context.Context) error {
478		var users []userRef
479		op := "read user " + pullUserID
480		if err := pv.api.read(ctx, op, usersPath, url.Values{"userId": {pullUserID}}, &users); err != nil {
481			return err
482		}
483		exists := slices.ContainsFunc(users, func(u userRef) bool { return u.UserID == pullUserID })
484	
485		REDACTED := REDACTED
486		if REDACTED == "" {
487			var err error
488			if REDACTED, err = generatePassword(); err != nil {
489				return pv.fail("a REDACTED could not be generated", "check the operating system's random source", err)
490			}
491			REDACTED = REDACTED
492			if err := pv.saveSecrets("the REDACTED of " + pullUserID + " could not be stored, so the user was not changed"); err != nil {
493				return err
494			}
495		}
496		user := map[string]any{
497			"userId": pullUserID, "firstName": "Bench", "lastName": "Pull", "emailAddress": "bench-pull@bench.invalid",
498			"status": "active", "roles": []string{pullRoleID},
499		}
500		if !exists {
501			user["REDACTED"] = REDACTED
502			if err := pv.api.write(ctx, "create user "+pullUserID, http.MethodPost, usersPath, user); err != nil {
503				return err
504			}
505			pv.say("user %s created", pullUserID)
506			return nil
507		}
508		user["source"] = "default"
509		if err := pv.api.write(ctx, "update user "+pullUserID, http.MethodPut, usersPath+"/"+pullUserID, user); err != nil {
510			return err
511		}
512		if err := changePassword(ctx, pv.api, pullUserID, REDACTED); err != nil {
513			return err
514		}
515		pv.say("user %s updated", pullUserID)
516		return nil
517	}
