15	const (
16		// clientTimeout bounds every REST call, connection included.
17		clientTimeout = 15 * time.Second
18		// maxResponseBytes is the most the client reads from one answer. A larger
19		// one is an error, and its content is never decoded.
20		maxResponseBytes = 1 << 20
21		// drainBytes is how much of an unwanted answer is read so the connection
22		// can be reused.
23		drainBytes = 4 << 10
24	)
25	
26	// APIError is a REST call the instance answered with a status outside 2xx. It
27	// carries the operation and the status only: no URL, no request body, no answer
28	// body, because any of them could hold a credential.
29	type APIError struct {
30		// Op says what the call was for, e.g. "create user bench-pull".
31		Op     string
32		Status int
33	}
34	
35	// Error returns "<Op>: HTTP <status> <text>".
36	func (e *APIError) Error() string {
37		return strings.TrimSpace(fmt.Sprintf("%s: HTTP %d %s", e.Op, e.Status, http.StatusText(e.Status)))
38	}
39	
40	// transportError is a call that got no answer: connection refused, reset,
41	// timeout. The cause stays in Err; its text carries the URL and is not printed.
42	type transportError struct {
43		Op  string
44		Err error
45	}
46	
47	func (e *transportError) Error() string { return "no answer to " + e.Op }
48	func (e *transportError) Unwrap() error { return e.Err }
49	
50	// tooLargeError is an answer past maxResponseBytes.
51	type tooLargeError struct{ Op string }
52	
53	func (e *tooLargeError) Error() string {
54		return fmt.Sprintf("the answer to %s is larger than %d bytes", e.Op, maxResponseBytes)
55	}
56	
57	// decodeError is an answer that is not the JSON the client expects.
58	type decodeError struct {
59		Op  string
60		Err error
61	}
62	
63	func (e *decodeError) Error() string { return "unexpected answer to " + e.Op }
64	func (e *decodeError) Unwrap() error { return e.Err }
65	
66	// client is the REST client of one Nexus instance. It follows no redirection
67	// (an answer that moves the call elsewhere would carry the credentials with
68	// it), reads at most maxResponseBytes of an answer, and never logs a header.
69	type client struct {
70		base     string
71		user     string
72		REDACTED string
73		http     *http.Client
74	}
75	
76	// newClient returns a client for baseURL, authenticating with Basic auth as user
77	// unless user is empty (the calls that need no account).
78	func newClient(baseURL, user, REDACTED string) *client {
79		transport := http.DefaultTransport.(*http.Transport).Clone()
80		// The bench is reached directly: a proxy named by the environment would
81		// receive the credentials.
82		transport.Proxy = nil
83		return &client{
84			base:     strings.TrimRight(baseURL, "/"),
85			user:     user,
86			REDACTED: REDACTED,
87			http: &http.Client{
88				Timeout:       clientTimeout,
89				Transport:     transport,
90				CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
91			},
92		}
93	}
94	
95	// closeIdle drops the connections the client keeps open.
96	func (c *client) closeIdle() { c.http.CloseIdleConnections() }
97	
98	// request is one REST call.
99	type request struct {
100		op          string
101		method      string
102		path        string
103		query       url.Values
104		contentType string
105		body        []byte
106	}
107	
108	// response is what the instance answered.
109	type response struct {
110		status int
111		header http.Header
112		body   []byte
113	}
114	
115	// do sends r and returns the answer whatever its status. The error is a
116	// *transportError or a *tooLargeError.
117	func (c *client) do(ctx context.Context, r request) (response, error) {
118		target := c.base + r.path
119		if len(r.query) > 0 {
120			target += "?" + r.query.Encode()
121		}
122		var body io.Reader
123		if r.body != nil {
124			body = bytes.NewReader(r.body)
125		}
126		req, err := http.NewRequestWithContext(ctx, r.method, target, body)
127		if err != nil {
128			return response{}, &transportError{Op: r.op, Err: err}
129		}
130		req.Header.Set("Accept", "application/json")
131		if r.contentType != "" {
132			req.Header.Set("Content-Type", r.contentType)
133		}
134		if c.user != "" {
135			req.SetBasicAuth(c.user, c.REDACTED)
136		}
137		resp, err := c.http.Do(req)
138		if err != nil {
139			return response{}, &transportError{Op: r.op, Err: err}
140		}
141		defer func() { _ = resp.Body.Close() }()
142		if resp.StatusCode < 200 || resp.StatusCode > 299 {
143			_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, drainBytes))
144			return response{status: resp.StatusCode, header: resp.Header}, nil
145		}
146		data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
147		if err != nil {
148			return response{}, &transportError{Op: r.op, Err: err}
149		}
150		if len(data) > maxResponseBytes {
151			return response{}, &tooLargeError{Op: r.op}
152		}
153		return response{status: resp.StatusCode, header: resp.Header, body: data}, nil
154	}
155	
156	// expect sends r and turns a status outside 2xx into an *APIError.
157	func (c *client) expect(ctx context.Context, r request) (response, error) {
158		resp, err := c.do(ctx, r)
159		if err != nil {
160			return resp, err
161		}
162		if resp.status < 200 || resp.status > 299 {
163			return resp, &APIError{Op: r.op, Status: resp.status}
164		}
165		return resp, nil
166	}
167	
168	// get reads path and decodes the JSON answer into out (nil: not decoded). A 404
169	// is found == false without an error.
170	func (c *client) get(ctx context.Context, op, path string, query url.Values, out any) (found bool, err error) {
171		resp, err := c.do(ctx, request{op: op, method: http.MethodGet, path: path, query: query})
172		if err != nil {
173			return false, err
174		}
175		switch {
176		case resp.status == http.StatusNotFound:
177			return false, nil
178		case resp.status < 200 || resp.status > 299:
179			return false, &APIError{Op: op, Status: resp.status}
180		}
181		if out == nil {
182			return true, nil
183		}
184		if err := json.Unmarshal(resp.body, out); err != nil {
185			return false, &decodeError{Op: op, Err: err}
186		}
187		return true, nil
188	}
189	
190	// read is get for an object that has to exist: a 404 is an *APIError.
191	func (c *client) read(ctx context.Context, op, path string, query url.Values, out any) error {
192		found, err := c.get(ctx, op, path, query, out)
193		if err != nil {
194			return err
195		}
196		if !found {
197			return &APIError{Op: op, Status: http.StatusNotFound}
198		}
199		return nil
200	}
201	
202	// write sends payload as JSON with method and expects a 2xx.
203	func (c *client) write(ctx context.Context, op, method, path string, payload any) error {
204		data, err := json.Marshal(payload)
205		if err != nil {
206			return &decodeError{Op: op, Err: err}
207		}
208		_, err = c.expect(ctx, request{op: op, method: method, path: path, contentType: "application/json", body: data})
209		return err
210	}
