1	package nexusbench
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"slices"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	const (
15		// fieldManager owns the fields the bench applies; a second apply under the
16		// same manager is a no-op, which is what makes a second up idempotent.
17		fieldManager = "devdesk-nexus-bench"
18	
19		// podSelector selects the Nexus pod, the label 20-deployment.yaml.tmpl sets.
20		podSelector = "app.kubernetes.io/name=nexus"
21	
22		// pollInterval separates two rounds of the wait.
23		pollInterval = 5 * time.Second
24	
25		// pendingGrace is how long a "cannot be scheduled" or "claim not bound"
26		// reading must last before it is reported: the scheduler and the volume
27		// provisioner settle within seconds on a healthy cluster.
28		pendingGrace = 30 * time.Second
29	
30		// applyTimeout bounds one apply, which may go through admission webhooks.
31		applyTimeout = "--request-timeout=30s"
32	
33		// Reasons of the container states the wait reacts to.
34		reasonErrImagePull     = "ErrImagePull"
35		reasonImagePullBackOff = "ImagePullBackOff"
36		reasonCrashLoop        = "CrashLoopBackOff"
37		reasonOOMKilled        = "OOMKilled"
38	)
39	
40	// Deploy applies the manifests of the bench and waits until Nexus answers on a
41	// NodePort. The order is fixed:
42	//
43	//  1. RunPreflight(OpUp): nothing is written before it succeeds
44	//  2. the context is looked at, then the Namespace is applied alone (server-side)
45	//  3. the whole stream of Render(p) is applied, the Namespace again included
46	//  4. a wait polls the pods and the claims of the namespace, diagnoses them
47	//     (PodPending, ImagePull, Crash), then asks the Prober about every host
48	//
49	// It returns as soon as one host answers, with the hosts that answered in that
50	// round; a host that stays mute is a warning on out. The deadline is
51	// Params.Timeout. Every failure is a *BenchError, but a cancelled context, which
52	// is returned as is. Neither the stderr of kubectl nor the error of the prober
53	// reaches a message; the Err of a BenchError keeps the former for errors.Is.
54	func Deploy(ctx context.Context, r Runner, pr Prober, clk Clock, p Params, out io.Writer) (DeployResult, error) {
55		if out == nil {
56			out = io.Discard
57		}
58		pre, err := RunPreflight(ctx, r, p, OpUp)
59		if err != nil {
60			return DeployResult{}, err
61		}
62		// The runner of a test may ignore ctx; the first write must not depend on it.
63		if err := ctx.Err(); err != nil {
64			return DeployResult{}, err
65		}
66		nsDoc, err := RenderNamespace(p)
67		if err != nil {
68			return DeployResult{}, fmt.Errorf("render the Namespace: %w", err)
69		}
70		fullDoc, err := Render(p)
71		if err != nil {
72			return DeployResult{}, fmt.Errorf("render the manifests: %w", err)
73		}
74	
75		d := &deployer{pf: preflight{r: r, p: p}, pr: pr, clk: clk, out: out, hosts: deployHosts(p, pre.NodeIP)}
76		d.say("applying the Namespace %s", p.Namespace)
77		if err := d.apply(ctx, "the Namespace", nsDoc); err != nil {
78			return DeployResult{}, err
79		}
80		d.say("applying the manifests")
81		if err := d.apply(ctx, "the manifests", fullDoc); err != nil {
82			return DeployResult{}, err
83		}
84		reached, err := d.wait(ctx)
85		if err != nil {
86			return DeployResult{}, err
87		}
88		return DeployResult{ReachableHosts: reached, NodeIP: pre.NodeIP}, nil
89	}
90	
91	// deployHosts are the hosts the NodePorts are tried on: Params.Hosts when set,
92	// else the loopback address and the node's InternalIP when there is one.
93	func deployHosts(p Params, nodeIP string) []string {
94		if len(p.Hosts) > 0 {
95			return slices.Clone(p.Hosts)
96		}
97		hosts := []string{loopbackHost}
98		if nodeIP != "" {
99			hosts = append(hosts, nodeIP)
100		}
101		return hosts
102	}
103	
104	// deployer is the state of one Deploy run.
105	type deployer struct {
106		pf    preflight // the runner and the parameters, and its error builders
107		pr    Prober
108		clk   Clock
109		out   io.Writer
110		hosts []string
111	
112		lastSaid     string      // the last state line, so a line is not repeated
113		pendingKey   string      // Cause of the pending reading being timed
114		pendingSince time.Time   // when that reading was first seen
115		candidate    *BenchError // the pending reading of the last round, if any
116	}
117	
118	func (d *deployer) say(format string, args ...any) {
119		_, _ = fmt.Fprintf(d.out, "deploy: "+format+"\n", args...)
120	}
121	
122	// ---- apply ------------------------------------------------------------------
123	
124	// apply sends doc to "kubectl apply --server-side". what names it in messages.
125	func (d *deployer) apply(ctx context.Context, what string, doc []byte) error {
126		args := []string{"apply", "--server-side", "--field-manager=" + fieldManager, "-f", "-", applyTimeout}
127		_, errOut, err := d.pf.r.Run(ctx, doc, args...)
128		if err == nil {
129			return nil
130		}
131		if cerr := ctx.Err(); cerr != nil {
132			return cerr
133		}
134		return d.applyFailure(what, string(errOut), err)
135	}
136	
137	// applyFailure classifies a failed apply from its stderr; the stderr itself is
138	// dropped from the message.
139	func (d *deployer) applyFailure(what, stderr string, err error) *BenchError {
140		p := d.pf.p
141		be := &BenchError{Kind: classifyKubectl(stderr), Err: err}
142		switch be.Kind {
143		case NodePortTaken:
144			be.Cause = "could not apply " + what + ": a NodePort is already allocated"
145			be.Check = d.pf.command("get", "services", "-A", "-o", "json") + ", then set " + envHTTPNodePort + " and " + envDockerNodePort + " to free ports"
146		case AdmissionDenied:
147			be.Cause = "could not apply " + what + ": an admission webhook denied the request"
148			be.Check = d.pf.command("get", "events", "-A", "--sort-by=.lastTimestamp") + ", then read the policy that denied it"
149		case Forbidden:
150			be.Cause = "could not apply " + what + ": the API server refused the request (forbidden)"
151			be.Check = d.pf.command("auth", "can-i", "--list", "-n", p.Namespace)
152		case ClusterUnreachable:
153			be.Cause = "could not apply " + what + ": the cluster did not answer"
154			be.Check = d.pf.command("get", "--raw", "/readyz")
155		default:
156			be.Kind = Unclassified
157			be.Cause = "kubectl failed to apply " + what
158			be.Check = "mise run nexus-bench:render, then " + d.pf.command("apply", "--server-side", "--dry-run=server", "-f", "-")
159		}
160		return be
161	}
162	
163	// ---- the wait ---------------------------------------------------------------
164	
165	// wait polls until a host answers, a diagnosis fails the run, or the deadline
166	// passes. A round reads, diagnoses, then probes; the deadline is looked at after
167	// the round, so the cluster is read once more at the very end.
168	func (d *deployer) wait(ctx context.Context) ([]string, error) {
169		deadline := d.clk.Now().Add(d.pf.p.Timeout)
170		for {
171			obs, err := d.observe(ctx)
172			if err != nil {
173				return nil, err
174			}
175			failure, pending := diagnose(d.pf.p, obs)
176			if failure != nil {
177				return nil, failure
178			}
179			d.candidate = pending
180			if err := d.trackPending(); err != nil {
181				return nil, err
182			}
183			d.report(obs)
184			reached, silent := d.probeHosts(ctx)
185			if err := ctx.Err(); err != nil {
186				return nil, err
187			}
188			if len(reached) > 0 {
189				d.warnSilent(reached, silent)
190				return reached, nil
191			}
192			if !d.clk.Now().Before(deadline) {
193				return nil, d.deadlineError(obs)
194			}
195			if err := d.clk.Sleep(ctx, pollInterval); err != nil {
196				return nil, err
197			}
198		}
199	}
200	
201	// trackPending returns the pending reading of the round once it has lasted for
202	// pendingGrace without a break; a reading that changes or goes away restarts the
203	// count, so a claim that binds when the pod is scheduled is not a failure.
204	func (d *deployer) trackPending() error {
205		if d.candidate == nil {
206			d.pendingKey = ""
207			return nil
208		}
209		if d.candidate.Cause != d.pendingKey {
210			d.pendingKey, d.pendingSince = d.candidate.Cause, d.clk.Now()
211		}
212		if d.clk.Now().Sub(d.pendingSince) >= pendingGrace {
213			return d.candidate
214		}
215		return nil
216	}
217	
218	// deadlineError is the end of a wait that ran out of time. A pending reading
219	// that was still there says more than the deadline does.
220	func (d *deployer) deadlineError(obs observation) error {
221		p := d.pf.p
222		if d.candidate != nil {
223			return d.candidate
224		}
225		return &BenchError{
226			Kind: Deadline,
227			Cause: fmt.Sprintf("Nexus did not answer on NodePort %d (tried %s) within %s; last state: %s",
228				p.HTTPNodePort, strings.Join(d.hosts, ", "), p.Timeout, obs.describe()),
229			Check: describePodCommand(p) + ", then raise " + envTimeout + " if the image pull or the start is only slow; `mise run nexus-bench:down` removes the bench",
230		}
231	}
232	
233	// report prints the state of the cluster when it changed since the last line.
234	func (d *deployer) report(obs observation) {
235		if line := obs.describe(); line != d.lastSaid {
236			d.lastSaid = line
237			d.say("%s", line)
238		}
239	}
240	
241	// probeHosts asks the Prober about every host at once and splits them into the
242	// ones that answered and the ones that did not, each in the order of d.hosts.
243	// The error of the prober is dropped: it names the URL and the cause is enough
244	// in the final message.
245	func (d *deployer) probeHosts(ctx context.Context) (reached, silent []string) {
246		urls := hostURLs(d.hosts, d.pf.p.HTTPNodePort)
247		ok := make([]bool, len(urls))
248		var wg sync.WaitGroup
249		for i, u := range urls {
250			wg.Go(func() { ok[i] = d.pr.Ready(ctx, u) == nil })
251		}
252		wg.Wait()
253		for i, host := range d.hosts {
254			if ok[i] {
255				reached = append(reached, host)
256			} else {
257				silent = append(silent, host)
258			}
259		}
260		return reached, silent
261	}
262	
263	func (d *deployer) warnSilent(reached, silent []string) {
264		for _, host := range silent {
265			d.say("warning: %s did not answer on NodePort %d, although %s did; it will not be listed (check that it is reachable from this machine)",
266				host, d.pf.p.HTTPNodePort, strings.Join(reached, ", "))
267		}
268	}
269	
270	// ---- reading the cluster ----------------------------------------------------
271	
272	// observation is what one round read: the pods of Nexus and its claim.
273	type observation struct {
274		pods []podObject
275		pvc  *claimObject
276	}
277	
278	type podObject struct {
279		Metadata struct {
280			Name              string  `json:"name"`
281			DeletionTimestamp *string `json:"deletionTimestamp"`
282		} `json:"metadata"`
283		Status struct {
284			Phase      string `json:"phase"`
285			Conditions []struct {
286				Type    string `json:"type"`
287				Status  string `json:"status"`
288				Reason  string `json:"reason"`
289				Message string `json:"message"`
290			} `json:"conditions"`
291			ContainerStatuses []containerStatus `json:"containerStatuses"`
292		} `json:"status"`
293	}
294	
295	type containerStatus struct {
296		Ready        bool `json:"ready"`
297		RestartCount int  `json:"restartCount"`
298		State        struct {
299			Waiting    *struct{ Reason string } `json:"waiting"`
300			Running    *struct{}                `json:"running"`
301			Terminated *struct{ Reason string } `json:"terminated"`
302		} `json:"state"`
303		LastState struct {
304			Terminated *struct{ Reason string } `json:"terminated"`
305		} `json:"lastState"`
306	}
307	
308	type claimObject struct {
309		Metadata struct {
310			Name string `json:"name"`
311		} `json:"metadata"`
312		Status struct {
313			Phase string `json:"phase"`
314		} `json:"status"`
315	}
316	
317	// observe reads the pods of Nexus and the claims of the namespace.
318	func (d *deployer) observe(ctx context.Context) (observation, error) {
319		var obs observation
320		ns := d.pf.p.Namespace
321		var pods struct {
322			Items []podObject `json:"items"`
323		}
324		if err := d.read(ctx, "read the Nexus pod", []string{"get", "pods", "-n", ns, "-l", podSelector, "-o", "json"}, &pods); err != nil {
325			return obs, err
326		}
327		var claims struct {
328			Items []claimObject `json:"items"`
329		}
330		if err := d.read(ctx, "read the volume claim", []string{"get", "pvc", "-n", ns, "-o", "json"}, &claims); err != nil {
331			return obs, err
332		}
333		obs.pods = pods.Items
334		if len(claims.Items) > 0 {
335			obs.pvc = &claims.Items[0]
336		}
337		return obs, nil
338	}
339	
340	// read runs a read-only kubectl call and decodes its JSON answer into into.
341	func (d *deployer) read(ctx context.Context, what string, args []string, into any) error {
342		out, errOut, err := d.pf.remote(ctx, args...)
343		if err != nil {
344			if cerr := ctx.Err(); cerr != nil {
345				return cerr
346			}
347			return d.pf.failure("could not "+what, args, string(errOut), err)
348		}
349		if err := json.Unmarshal([]byte(out), into); err != nil {
350			return &BenchError{
351				Kind:  Unclassified,
352				Cause: "kubectl answered with something that is not the answer to \"" + what + "\"",
353				Check: d.pf.command(args...),
354				Err:   err,
355			}
356		}
357		return nil
358	}
359	
360	// describe is the one-line state of the round, for the progress and the deadline.
361	func (o observation) describe() string {
362		var parts []string
363		if len(o.pods) == 0 {
364			parts = append(parts, "no pod matches "+podSelector+" yet")
365		}
366		for _, pod := range o.pods {
367			parts = append(parts, pod.describe())
368		}
369		if o.pvc == nil {
370			parts = append(parts, "no volume claim yet")
371		} else {
372			parts = append(parts, fmt.Sprintf("claim %s is %s", o.pvc.Metadata.Name, o.pvc.Status.Phase))
373		}
374		return strings.Join(parts, "; ")
375	}
376	
377	func (pod podObject) describe() string {
378		s := fmt.Sprintf("pod %s: phase %s", pod.Metadata.Name, pod.Status.Phase)
379		if len(pod.Status.ContainerStatuses) == 0 {
380			if _, ok := pod.unschedulable(); ok {
381				return s + ", cannot be scheduled"
382			}
383			return s + ", not started"
384		}
385		cs := pod.Status.ContainerStatuses[0]
386		switch {
387		case cs.State.Waiting != nil:
388			return s + ", container waiting (" + cs.State.Waiting.Reason + ")"
389		case cs.State.Running != nil && cs.Ready:
390			return s + ", container running and ready"
391		case cs.State.Running != nil:
392			return s + ", container running, not ready"
393		}
394		return s + ", container not running"
395	}
396	
397	// ---- diagnosis --------------------------------------------------------------
398	
399	// diagnose reads a round. failure is a state that ends the wait at once;
400	// pending is a state that does (when it lasts) but may also be passing.
401	func diagnose(p Params, obs observation) (failure, pending *BenchError) {
402		for _, pod := range obs.pods {
403			if pod.Metadata.DeletionTimestamp != nil {
404				continue
405			}
406			if f := podFailure(p, pod); f != nil {
407				return f, nil
408			}
409		}
410		return nil, pendingReading(p, obs)
411	}
412	
413	// podFailure is a pull that fails or a container that crashes.
414	func podFailure(p Params, pod podObject) *BenchError {
415		for _, cs := range pod.Status.ContainerStatuses {
416			waiting := ""
417			if cs.State.Waiting != nil {
418				waiting = cs.State.Waiting.Reason
419			}
420			last := ""
421			switch {
422			case cs.LastState.Terminated != nil:
423				last = cs.LastState.Terminated.Reason
424			case cs.State.Terminated != nil:
425				last = cs.State.Terminated.Reason
426			}
427			switch {
428			case waiting == reasonErrImagePull || waiting == reasonImagePullBackOff:
429				return &BenchError{
430					Kind:  ImagePull,
431					Cause: fmt.Sprintf("the image %s could not be pulled (%s)", p.ImageRef(), waiting),
432					Check: describePodCommand(p) + ", then check " + envImage + ", " + envImageTag + " and the access of the cluster to the registry",
433				}
434			case waiting == reasonCrashLoop || last == reasonOOMKilled:
435				return crashFailure(p, waiting, last)
436			}
437		}
438		return nil
439	}
440	
441	func crashFailure(p Params, waiting, last string) *BenchError {
442		state := "restarted"
443		if waiting != "" {
444			state = waiting
445		}
446		if last == "" {
447			last = "unknown"
448		}
449		return &BenchError{
450			Kind:  Crash,
451			Cause: fmt.Sprintf("the Nexus container keeps crashing (%s, last termination: %s) with a memory limit of %s", state, last, p.MemoryLimit),
452			Check: describePodCommand(p) + " and `kubectl --context " + p.Context + " -n " + p.Namespace + " logs deploy/nexus --previous`; raise " + envMemoryLimit + " when it was " + reasonOOMKilled,
453		}
454	}
455	
456	// pendingReading is a pod that cannot be scheduled, or a claim that stays
457	// Pending although a pod is scheduled. The pod comes first: while it is not
458	// scheduled, a claim of a WaitForFirstConsumer class is Pending for that reason
459	// alone.
460	func pendingReading(p Params, obs observation) *BenchError {
461		scheduled := false
462		for _, pod := range obs.pods {
463			if pod.Metadata.DeletionTimestamp != nil {
464				continue
465			}
466			if msg, ok := pod.unschedulable(); ok {
467				return unschedulableReading(p, msg)
468			}
469			scheduled = scheduled || pod.scheduled()
470		}
471		if scheduled && obs.pvc != nil && obs.pvc.Status.Phase == "Pending" {
472			return &BenchError{
473				Kind:  PodPending,
474				Cause: fmt.Sprintf("the volume claim %s (%s of storage) is still Pending although the pod is scheduled", obs.pvc.Metadata.Name, p.StorageSize),
475				Check: kubectlIn(p, "describe", "pvc", obs.pvc.Metadata.Name) + ", then lower " + envStorageSize + " or check the default StorageClass",
476			}
477		}
478		return nil
479	}
480	
481	func unschedulableReading(p Params, msg string) *BenchError {
482		var lacks, envs []string
483		if strings.Contains(msg, "Insufficient memory") {
484			lacks = append(lacks, "memory (requested "+p.MemoryRequest+")")
485			envs = append(envs, envMemoryRequest)
486		}
487		if strings.Contains(msg, "Insufficient cpu") {
488			lacks = append(lacks, "cpu (requested "+p.CPURequest+")")
489			envs = append(envs, envCPURequest)
490		}
491		be := &BenchError{Kind: PodPending, Cause: "the Nexus pod cannot be scheduled", Check: describePodCommand(p)}
492		if len(lacks) > 0 {
493			be.Cause += ": the node has not enough " + strings.Join(lacks, " and ") + " left"
494			be.Check += ", then lower " + strings.Join(envs, " or ")
495		}
496		return be
497	}
498	
499	// scheduled reports whether the PodScheduled condition is True.
500	func (pod podObject) scheduled() bool {
501		for _, c := range pod.Status.Conditions {
502			if c.Type == "PodScheduled" && c.Status == "True" {
503				return true
504			}
505		}
506		return false
507	}
508	
509	// unschedulable returns the message of the Unschedulable PodScheduled=False
510	// condition, and whether the pod has one.
511	func (pod podObject) unschedulable() (message string, ok bool) {
512		for _, c := range pod.Status.Conditions {
513			if c.Type == "PodScheduled" && c.Status == "False" && c.Reason == "Unschedulable" {
514				return c.Message, true
515			}
516		}
517		return "", false
518	}
519	
520	// describePodCommand is the kubectl command that describes the Nexus pod.
521	func describePodCommand(p Params) string {
522		return kubectlIn(p, "describe", "pod", "-l", podSelector)
523	}
524	
525	// kubectlIn is a kubectl command line, in the namespace of the bench, a user can
526	// run to repeat a diagnosis.
527	func kubectlIn(p Params, args ...string) string {
528		return "kubectl --context " + p.Context + " -n " + p.Namespace + " " + strings.Join(args, " ")
529	}
