270	// ---- reading the cluster ----------------------------------------------------
271	
272	// observation is what one round read: the pods of Nexus and its claim.
273	type observation struct {
274		pods []podObject
275		pvc  *claimObject
276	}
277	
278	type podObject struct {
279		Metadata struct {
280			Name              string  `json:"name"`
281			DeletionTimestamp *string `json:"deletionTimestamp"`
282		} `json:"metadata"`
283		Status struct {
284			Phase      string `json:"phase"`
285			Conditions []struct {
286				Type    string `json:"type"`
287				Status  string `json:"status"`
288				Reason  string `json:"reason"`
289				Message string `json:"message"`
290			} `json:"conditions"`
291			ContainerStatuses []containerStatus `json:"containerStatuses"`
292		} `json:"status"`
293	}
294	
295	type containerStatus struct {
296		Ready        bool `json:"ready"`
297		RestartCount int  `json:"restartCount"`
298		State        struct {
299			Waiting    *struct{ Reason string } `json:"waiting"`
300			Running    *struct{}                `json:"running"`
301			Terminated *struct{ Reason string } `json:"terminated"`
302		} `json:"state"`
303		LastState struct {
304			Terminated *struct{ Reason string } `json:"terminated"`
305		} `json:"lastState"`
306	}
307	
308	type claimObject struct {
309		Metadata struct {
310			Name string `json:"name"`
311		} `json:"metadata"`
312		Status struct {
313			Phase string `json:"phase"`
314		} `json:"status"`
315	}
