317	// observe reads the pods of Nexus and the claims of the namespace.
318	func (d *deployer) observe(ctx context.Context) (observation, error) {
319		var obs observation
320		ns := d.pf.p.Namespace
321		var pods struct {
322			Items []podObject `json:"items"`
323		}
324		if err := d.read(ctx, "read the Nexus pod", []string{"get", "pods", "-n", ns, "-l", podSelector, "-o", "json"}, &pods); err != nil {
325			return obs, err
326		}
327		var claims struct {
328			Items []claimObject `json:"items"`
329		}
330		if err := d.read(ctx, "read the volume claim", []string{"get", "pvc", "-n", ns, "-o", "json"}, &claims); err != nil {
331			return obs, err
332		}
333		obs.pods = pods.Items
334		if len(claims.Items) > 0 {
335			obs.pvc = &claims.Items[0]
336		}
337		return obs, nil
338	}
339	
340	// read runs a read-only kubectl call and decodes its JSON answer into into.
341	func (d *deployer) read(ctx context.Context, what string, args []string, into any) error {
342		out, errOut, err := d.pf.remote(ctx, args...)
343		if err != nil {
344			if cerr := ctx.Err(); cerr != nil {
345				return cerr
346			}
347			return d.pf.failure("could not "+what, args, string(errOut), err)
348		}
349		if err := json.Unmarshal([]byte(out), into); err != nil {
350			return &BenchError{
351				Kind:  Unclassified,
352				Cause: "kubectl answered with something that is not the answer to \"" + what + "\"",
353				Check: d.pf.command(args...),
354				Err:   err,
355			}
356		}
357		return nil
358	}
359	
360	// describe is the one-line state of the round, for the progress and the deadline.
361	func (o observation) describe() string {
362		var parts []string
363		if len(o.pods) == 0 {
364			parts = append(parts, "no pod matches "+podSelector+" yet")
365		}
366		for _, pod := range o.pods {
367			parts = append(parts, pod.describe())
368		}
369		if o.pvc == nil {
370			parts = append(parts, "no volume claim yet")
371		} else {
372			parts = append(parts, fmt.Sprintf("claim %s is %s", o.pvc.Metadata.Name, o.pvc.Status.Phase))
373		}
374		return strings.Join(parts, "; ")
375	}
376	
377	func (pod podObject) describe() string {
378		s := fmt.Sprintf("pod %s: phase %s", pod.Metadata.Name, pod.Status.Phase)
379		if len(pod.Status.ContainerStatuses) == 0 {
380			if _, ok := pod.unschedulable(); ok {
381				return s + ", cannot be scheduled"
382			}
383			return s + ", not started"
384		}
385		cs := pod.Status.ContainerStatuses[0]
386		switch {
387		case cs.State.Waiting != nil:
388			return s + ", container waiting (" + cs.State.Waiting.Reason + ")"
389		case cs.State.Running != nil && cs.Ready:
390			return s + ", container running and ready"
391		case cs.State.Running != nil:
392			return s + ", container running, not ready"
393		}
394		return s + ", container not running"
395	}
